      const closeWarkatDetailBtn = document.getElementById('btn-close-warkat-detail');
      const closeWarkatDetailAction = document.getElementById('btn-warkat-modal-close-action');
      const inspectButtons = document.querySelectorAll('.btn-inspect-warkat');
      const singlePrintButtons = document.querySelectorAll('.btn-print-single');

      // Print Sheet Modal Handlers
      if (openPrintBtn && printModal) {
        openPrintBtn.addEventListener('click', () => {
          printModal.classList.remove('hidden');
          printModal.classList.add('flex');
          document.body.style.overflow = 'hidden';
        });
      }

      if (closePrintBtn && printModal) {
        closePrintBtn.addEventListener('click', () => {
          printModal.classList.add('hidden');
          printModal.classList.remove('flex');
          document.body.style.overflow = '';
        });
      }

      if (triggerPrintBtn) {
        triggerPrintBtn.addEventListener('click', () => {
          window.print();
        });
      }

      // Close modal on backdrop click
      if (printModal) {
        printModal.addEventListener('click', (e) => {
          if (e.target === printModal) {
            printModal.classList.add('hidden');
            printModal.classList.remove('flex');
            document.body.style.overflow = '';
          }
        });
      }

      // Delegate to DracoRent engine for Date Range CSV Export Modal
      if (exportCsvBtn) {
        exportCsvBtn.addEventListener('click', (e) => {
          e.preventDefault();
          if (window.openDracoExportModal) {
            window.openDracoExportModal();
          }
        });
      }

      // Dynamic Real Filtering Engine
      function filterData() {
        const query = (searchInput?.value || '').toLowerCase().trim();
        const selectedStatus = statusFilter?.value || 'all';
        const selectedOrdo = ordoFilter?.value || 'all';

        tableRows.forEach(row => {
          const text = row.textContent.toLowerCase();
          const matchesQuery = query === '' || text.includes(query);

          let matchesStatus = true;
          if (selectedStatus === 'ontime') {
            matchesStatus = text.includes('tepat waktu');
          } else if (selectedStatus === 'fined') {
            matchesStatus = text.includes('terlambat') || text.includes('rp50.000') || text.includes('rp100.000');
          }

          let matchesOrdo = true;
          if (selectedOrdo === 'wyrm') {
            matchesOrdo = text.includes('wyrm api');
          } else if (selectedOrdo === 'wyvern') {
            matchesOrdo = text.includes('wyvern badai');
          } else if (selectedOrdo === 'frost') {
            matchesOrdo = text.includes('frost drake');
          } else if (selectedOrdo === 'lindworm') {
            matchesOrdo = text.includes('lindworm');
          }

          if (matchesQuery && matchesStatus && matchesOrdo) {
            row.style.display = '';
          } else {
            row.style.display = 'none';
          }
        });
      }

      if (searchInput) searchInput.addEventListener('input', filterData);
      if (statusFilter) statusFilter.addEventListener('change', filterData);
      if (ordoFilter) ordoFilter.addEventListener('change', filterData);

      if (resetFilterBtn) {
        resetFilterBtn.addEventListener('click', () => {
          if (searchInput) searchInput.value = '';
          if (statusFilter) statusFilter.value = 'all';
          if (ordoFilter) ordoFilter.value = 'all';
          filterData();
        });
      }

      // Individual Warkat Inspection
      inspectButtons.forEach(btn => {
        btn.addEventListener('click', () => {
          const trxId = btn.getAttribute('data-trx');
          const trxLabel = document.getElementById('warkat-modal-trx-id');
          if (trxLabel) trxLabel.textContent = trxId;
          if (warkatModal) {
            warkatModal.classList.remove('hidden');
            warkatModal.classList.add('flex');
          }
        });
      });

      singlePrintButtons.forEach(btn => {
        btn.addEventListener('click', () => {
          // Trigger print report modal pre-focused
          if (printModal) {
            printModal.classList.remove('hidden');
            printModal.classList.add('flex');
          }
        });
      });

      function closeWarkatDetail() {
        if (warkatModal) {
          warkatModal.classList.add('hidden');
          warkatModal.classList.remove('flex');
        }
      }

      if (closeWarkatDetailBtn) closeWarkatDetailBtn.addEventListener('click', closeWarkatDetail);
      if (closeWarkatDetailAction) closeWarkatDetailAction.addEventListener('click', closeWarkatDetail);
    })();
  </script>
</div></main></div><script>
(function() {
  const pathMap = {
    'masuk': 'masuk.html',
    'masuk-kurator': 'masuk.html',
    'keluar': 'masuk.html',
    'ringkasan': 'ringkasan.html',
    'unit-naga': 'unit-naga.html',
    'tambah-unit-modal': 'tambah-unit-modal.html',
    'kategori': 'kategori.html',
    'anggota': 'anggota.html',
    'pinjaman-aktif': 'pinjaman-aktif.html',
    'riwayat-dan-laporan': 'riwayat-dan-laporan.html',
    'katalog-naga': 'katalog-naga.html',
    'katalog-publik': 'katalog-naga.html',
    'detail-naga': 'detail-naga.html',
    'pinjaman-saya': 'pinjaman-saya.html',
    'riwayat-rental': 'riwayat-rental.html',
    'profil-saya': 'profil-saya.html'
  };

  function navigateTo(slug) {
    const target = pathMap[slug] || (slug + '.html');
    if (window.parent && window.parent !== window && window.parent.switchDracoScreen) {
      window.parent.switchDracoScreen(slug);
      return;
    }
    const inScreensDir = window.location.pathname.replace(/\\/g, '/').includes('/screens/');
    window.location.href = inScreensDir ? target : ('screens/' + target);
  }

  document.addEventListener('DOMContentLoaded', function() {
    document.querySelectorAll('[data-path]').forEach(function(el) {
      el.addEventListener('click', function(e) {
        const p = el.getAttribute('data-path');
        if (p && pathMap[p]) {
          e.preventDefault();
          navigateTo(p);
        }
      });
    });

    // Wire catalog detail & rent buttons to detail-naga screen
    document.querySelectorAll('.view-detail-btn, .rent-action-btn').forEach(function(btn) {
      btn.addEventListener('click', function(e) {
        e.preventDefault();
        navigateTo('detail-naga');
      });
    });

    // Wire breadcrumb back to catalog
    document.querySelectorAll('a').forEach(function(a) {
      const txt = (a.textContent || '').trim();
      if (txt.includes('Kembali ke Katalog')) {
        a.addEventListener('click', function(e) {
          e.preventDefault();
          navigateTo('katalog-naga');
        });
      }
      if (txt.includes('Lihat Semua Kontrak')) {
        a.addEventListener('click', function(e) {
          e.preventDefault();
          navigateTo('pinjaman-aktif');
        });
      }
    });

    // Wire Proses Pengembalian buttons on dashboard
    document.querySelectorAll('button').forEach(function(btn) {
      const txt = (btn.textContent || '').trim();
      if (txt.includes('Proses Pengembalian')) {
        btn.addEventListener('click', function(e) {
          e.preventDefault();
          navigateTo('pinjaman-aktif');
        });
      }
      if (txt.includes('+ Tambah Unit Baru') || txt.includes('Tambah Unit Naga')) {
        btn.addEventListener('click', function(e) {
          if (!document.getElementById('modal-backdrop') && !window.location.pathname.includes('tambah-unit-modal')) {
            e.preventDefault();
            navigateTo('tambah-unit-modal');
          }
        });
      }
      if (txt.includes('Kelola Kategori')) {
        btn.addEventListener('click', function(e) {
          e.preventDefault();
          navigateTo('kategori');
        });
      }
      if (txt.includes('+ Tambah Anggota Serikat') && !document.getElementById('panel-tambah-anggota')) {
        btn.addEventListener('click', function(e) {
          e.preventDefault();
          navigateTo('anggota');
        });
      }
      if (txt.includes('Semua Pinjaman Aktif')) {
        btn.addEventListener('click', function(e) {
          e.preventDefault();
          navigateTo('pinjaman-aktif');
        });
      }
    });

    // Wire login form submit
    const loginForm = document.getElementById('loginForm');
    if (loginForm) {
      loginForm.addEventListener('submit', function(e) {
        e.preventDefault();
        const emailVal = (document.getElementById('email')?.value || '').toLowerCase();
        if (emailVal.includes('admin') || emailVal.includes('kaelen') || emailVal.includes('kurator')) {
          navigateTo('ringkasan');
        } else {
          navigateTo('katalog-naga');
        }
      });
    }
  });
})();
</script>
<script src="/js/dracorent-app.js"></script></body></html>
